        '새 적 도망자 — 공격하지 않고, 체력 2400에 아주 빠릅니다. 맞을 때마다 플레이어 반대쪽 무작위 방향으로 달아났다 멈춥니다. 잡으면 스킬을 반드시 떨어뜨리고, 나타난 지 1분 뒤엔 사라집니다. 무지개빛으로 색이 바뀌는 별 모양이며, 화면 밖에 있으면 가장자리에 금빛 화살표가 가리킵니다. 40초에 처음, 그 뒤 75초마다 한 마리씩 나타납니다.',
