        '고대 두개골을 적용한 판에서는 희귀 적이 나오지 않습니다 — 희귀 적이 나올 자리에 우두머리가 나오고, 우두머리가 이미 3마리면 일반 적이 나옵니다. 제단이 부르는 희귀 적도 마찬가지입니다.',
        '장비 속성에서 예리(공격력 +)와 재생(5초당 체력 +)을 없앴습니다. 고정 공격력은 검의 단계에서만, 체력 회복은 물약에서만 얻습니다. 둘이 붙어 있던 무기는 그 줄만 빠집니다.',
        '장비창이 인벤토리가 되었습니다 — 장비 탭과 소모품 탭이 있고, 각 탭은 가로 6칸 세로 12칸 격자에 아이콘으로 담깁니다. 테두리 색이 희귀도, 착용 중인 무기엔 모서리 표시. 72개를 넘으면 쪽이 넘어갑니다.',
        '방향키·마우스 올리기·칸 누르기로 고르면 오른쪽(세로 화면은 아래)에 설명과 할 수 있는 일이 나옵니다. 칸을 누르기만 해서는 착용하지 않습니다 — 착용 버튼이나 Space. Tab(또는 Q·E)으로 탭을 바꿉니다.',
