        '敵に触れると、触れている敵ごとに被害を受けます — 敵ごとに 0.6 秒のクールダウンがあり、3 体に囲まれれば 3 回当たります。投射物は以前どおり当たった後に少し無敵になります。',
        '基本攻撃がなくなりました — 回はスキル 3 枚から 1 つを選んで始まります。打撃も他のスキルと同じくドロップします。',
