        '新しいドロップ「ランダムスキル」— 敵が 1% の確率で落とします。拾うと 3 枚のスキルから 1 つを選び、持っているスキルならその強化選択肢が開きます。代わりに特定スキルのドロップ率は 3% から 1.5% になり、ボスは変わらず必ず落とします。',
        '新スキル「落雷」（オーラ · 呪文 · 雷）— 1 秒ごとに周囲 200 以内の敵ひとりに雷を落とします。被害 96。その敵が倒れると 50% の確率ですぐもう一度落ち、また倒せばまた判定します。',
        '火球が最初に当たった場所で弾けます — 半径 30 以内の他の敵も同じ被害を受けます。',
